package main 

 import ( 
 	"fmt" 
 	"net/http" 
 	"os" 
 ) 

 func healthHandler(w http.ResponseWriter, r *http.Request) { 
 	w.WriteHeader(http.StatusOK) 
 	fmt.Fprint(w, "ok") 
 } 

 func main() { 
 	port := os.Getenv("PORT") 
 	if port == "" { 
 		port = "8080" 
 	} 
 	http.HandleFunc("/health", healthHandler) 
 	fmt.Printf("Listening on :%s
", port) 
 	http.ListenAndServe(":"+port, nil) 
 }

