use std::collections::HashMap; 

 pub struct Config { 
     host: String, 
     port: u16, 
     workers: usize, 
 } 

 impl Config { 
     pub fn from_env() -> Self { 
         Config { 
             host: std::env::var("HOST").unwrap_or_else(|_| "0.0.0.0".into()), 
             port: std::env::var("PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(8080), 
             workers: num_cpus::get(), 
         } 
     } 
 }

